'use strict';
(() => {
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const human = value => String(value ?? '').replaceAll('_', ' ').replaceAll('-', ' ');
  const num = value => Number.isFinite(value) ? value.toLocaleString('en-GB') : 'Not recorded';
  const cash = value => Number.isFinite(value) ? '$' + value.toFixed(6) : 'Unknown';
  const states = {case:'all',model:'all',track:'all',state:'all'};
  let data, selected = null;
  const analysis = () => data.analysis;
  const attempts = () => analysis()?.attempts || [];
  const names = id => data.case_bank.cases.find(c => c.id === id)?.title || (id === 'legacy-contested' ? 'Legacy disputed propositions' : human(id));
  const isComplete = row => ['completed','complete','success','succeeded'].includes(row.state);
  const hasIssue = row => !row.structural_valid || (row.divergences || 0) > 0 || (row.missing || 0) > 0 || (row.unassessed || 0) > 0;
  const visible = () => attempts().filter(r => (states.case === 'all' || r.case_id === states.case) && (states.model === 'all' || r.model === states.model) && (states.track === 'all' || r.track === states.track) && (states.state === 'all' || (states.state === 'issues' ? hasIssue(r) : states.state === 'completed' ? isComplete(r) : r.state === states.state))).sort((a,b) => a.case_id.localeCompare(b.case_id) || a.model.localeCompare(b.model) || a.track.localeCompare(b.track) || a.id.localeCompare(b.id));
  const safeHref = path => {
    if (typeof path !== 'string' || !path || path.split('/').includes('..')) return null;
    if (/^https:\/\/github\.com\/sev7enITA\/PALO-BlueprintBench\//.test(path)) return path;
    if (/^[a-z]+:/i.test(path) || path.startsWith('/')) return null;
    return `https://github.com/sev7enITA/PALO-BlueprintBench/blob/${encodeURIComponent(data.source_reference)}/${data.campaign_path}/${path.split('/').map(encodeURIComponent).join('/')}`;
  };
  const link = (path,label) => {const href = safeHref(path); return href ? `<a href="${esc(href)}" target="_blank" rel="noopener">${esc(label)} ↗</a>` : '';};
  const options = (element, values) => {for (const [id,label] of values) {const option=document.createElement('option');option.value=id;option.textContent=label;element.append(option);}};
  const observationFor = id => data.postrun_semantic_observations?.observations?.find(item=>item.probe_id===id);
  const ambiguityBadge = id => observationFor(id)?'<small class="advisory-marker">Postrun rubric ambiguity noted; both readings defensible. Count retained.</small>':'';
  const configFor = row => data.configurations?.find(c=>c.id===row.model);
  const configLabel = row => `<strong>${esc(configFor(row)?.name || row.model)}</strong><small>${esc(row.model)} · provider ${esc(configFor(row)?.provider || 'unrecorded')}</small>`;
  const legacyDisplay = id => {const original=data.legacy_identity_map?.items?.find(item=>item.review_item===id)?.original_probe_id;return original?`${id} → ${original}`:id;};
  const packetFor = row => data.task_packets.find(t => t.id === row.task_id)?.packet;
  const unitMap = row => new Map((packetFor(row)?.documents || []).flatMap(d => d.units.map(u => [u.id,u.text])));
  function stateTag(row) {
    const kind = row.state === 'not_run' ? '' : !row.structural_valid ? 'warn' : (row.divergences || 0) ? 'warn' : 'good';
    return `<span class="tag ${kind}">${esc(human(row.state))}</span><small>${row.structural_valid ? 'Contract accepted' : row.state === 'not_run' ? 'No response assessed' : 'Contract not accepted'}</small>`;
  }
  function summary() {
    const a=analysis();
    if (!a) {$('load-state').textContent='Test preparation is published. No execution outcomes are available in this snapshot.';$('load-state').classList.add('warn');$('campaign-summary').innerHTML='';return;}
    $('load-state').textContent='Maintainer-led observations. Completed provider requests, contract validity and draft-label comparisons are separate.';
    const completed=a.completed_requests, assigned=a.assigned_requests;
    const measured=attempts().filter(r=>r.structural_valid).length;
    const remaining=attempts().filter(r=>r.state==='not_run').length;
    const group=[['Assigned requests',assigned],['Requests recorded',a.recorded_requests],['Provider completed',completed],['Contracts accepted',measured],['Not run',remaining]];
    $('campaign-summary').innerHTML=group.map(([label,value])=>`<div class="stat"><strong>${num(value)}</strong><span>${label}</span></div>`).join('');
    if (!assigned) $('load-state').textContent='No request assignments are recorded in this snapshot.';
  }
  function budget() {
    const b=data.budget;
    if (!b) {$('budget').innerHTML='<p>Budget accounting has not been published for this snapshot. No cost is substituted with zero.</p>';return;}
    const max=b.authorised_total_usd, bound=b.conservative_cumulative_bound_usd;
    const width=Number.isFinite(bound)&&Number.isFinite(max)&&max>0?Math.min(100,Math.max(0,bound/max*100)):0;
    $('budget').innerHTML=`<p><strong>Test charge ${cash(b.campaign_known_usd)}</strong> · authorised total ${cash(max)} · conservative cumulative bound ${cash(bound)} · remaining authorised headroom ${cash(b.remaining_authorised_headroom_usd)}</p><div class="budget-line" aria-hidden="true"><span style="width:${width}%"></span></div><p>Provider-reported account usage ${cash(b.account_usage_usd)}; prior unresolved reserve ${cash(b.previous_unresolved_reserve_usd)}; current unresolved reserve ${cash(b.current_unknown_reserve_usd)}. Reservations are not invoices or proven charges. The test ceiling is ${cash(b.campaign_ceiling_usd)}. The overall ceiling includes earlier work; it is not a separate allowance for each model.</p>`;
  }
  function chart() {
    if (!analysis()) {$('case-chart').innerHTML='<p class="small">Case completion bars appear only after a retained execution record exists.</p>';return;}
    $('case-chart').innerHTML=data.case_bank.cases.map(c=>{const own=attempts().filter(r=>r.case_id===c.id),total=own.length,complete=own.filter(isComplete).length,notrun=own.filter(r=>r.state==='not_run').length,failed=total-complete-notrun;return `<article class="case-bar"><div class="bar-label"><strong>${esc(c.title)}</strong><span>${complete}/${total} provider completed</span></div><div class="bar" role="img" aria-label="${complete} complete, ${failed} other recorded outcomes, ${notrun} not run out of ${total} assigned requests"><span class="complete" style="width:${total?complete/total*100:0}%"></span><span class="failed" style="width:${total?failed/total*100:0}%"></span><span class="notrun" style="width:${total?notrun/total*100:0}%"></span></div><div class="bar-note">${complete} complete · ${failed} other recorded outcomes · ${notrun} not run. Request completion is not semantic correctness.</div></article>`;}).join('');
  }
  function table() {
    const rows=visible();
    $('selection-status').textContent=`${rows.length} of ${attempts().length} assigned request records shown. Alphabetical order. No numerical ranks. Received but invalid judgments are unassessed, not semantic errors.`;
    if (!rows.length) {$('request-table').innerHTML='<p class="empty">No retained request records match this selection.</p>';return;}
    $('request-table').innerHTML=`<table><caption>SIX-PROCESS SYNTHETIC TEST · FIXED ASSIGNMENTS · PROVISIONAL EXPECTATIONS</caption><thead><tr><th>Process description / task</th><th>Configuration</th><th>Request / contract</th><th>Classified / assigned</th><th>Draft matches / scored assignments</th><th>Divergences</th><th>Missing / unassessed</th><th>Known USD</th><th>Observed time</th><th>Evidence</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.id===selected?'selected':''}"><td><strong>${esc(names(r.case_id))}</strong><small>${esc(human(r.track))} · ${esc(human(r.variant||'base'))}</small></td><td>${configLabel(r)}</td><td>${stateTag(r)}</td><td class="numeric">${num(r.classified)} / ${num(r.assigned)}<small>${num(r.unscored_classified||0)} classified without scoring</small></td><td class="numeric">${r.scored_assigned>0?num(r.matches_draft)+' / '+num(r.scored_assigned):'Not scored'}<small>Draft-key comparison</small></td><td class="numeric">${r.scored_assigned>0?num(r.divergences):'Not scored'}</td><td class="numeric">${num(r.missing)} / ${num(r.unassessed)}<small>Different outcomes</small></td><td class="numeric">${r.cost_status==='not_dispatched'?'Not dispatched':cash(r.cost_usd)}<small>${esc(human(r.cost_status || 'unknown'))}</small></td><td class="numeric">${Number.isFinite(r.elapsed_seconds)?r.elapsed_seconds.toFixed(2)+' s':'Not recorded'}</td><td><button class="quiet" data-inspect="${esc(r.id)}">Inspect ↗</button>${r.blueprint_path?'<small>Draft export retained</small>':''}</td></tr>`).join('')}</tbody></table>`;
    $('request-table').querySelectorAll('[data-inspect]').forEach(button=>button.addEventListener('click',()=>{selected=button.dataset.inspect;table();detail();$('request-detail').focus();$('request-detail').scrollIntoView({block:'start',behavior:'instant'});}));
  }
  function detail() {
    const r=attempts().find(row=>row.id===selected),host=$('request-detail');
    if (!r || !visible().some(row=>row.id===selected)) {host.hidden=true;return;}
    host.hidden=false;host.className='detail';
    const packet=packetFor(r),units=unitMap(r);
    const judgments=(r.judgments||[]).map(j=>`<tr><td>${esc(r.track==='legacy'?legacyDisplay(j.id):j.id)}</td><td>${esc(human(j.predicted))}</td><td>${j.matches_draft===null||j.matches_draft===undefined?'Unscored':j.matches_draft?'Matches draft':'Differs from draft'}<small>${j.draft_expected==null?'No adjudicated comparison key':esc(human(j.draft_expected))}</small>${ambiguityBadge(j.id)}</td><td>${(j.source_units||[]).map(id=>`<details><summary>${esc(id)}</summary><p>${esc(units.get(id)||'Source text unavailable in this packet')}</p></details>`).join('')}</td><td>${esc(j.rationale||'No rationale recorded')}</td></tr>`).join('');
    host.innerHTML=`<div class="detail-head"><div><p class="eyebrow">${esc(human(r.track))}</p><h3>${esc(names(r.case_id))}</h3><p class="small">${esc(r.model)} · ${esc(r.id)}</p></div><button class="quiet" id="close-detail">Close ×</button></div><dl><dt>Access channel</dt><dd>OpenRouter API</dd><dt>Serving provider</dt><dd>${esc(configFor(r)?.provider || "Not recorded")}</dd><dt>Configured reasoning / output cap</dt><dd>${esc(data.protocol?.reasoning_effort || "Not recorded")} / ${num(data.protocol?.max_output_tokens)} output tokens; configured ceiling, not observed usage or tested context capacity</dd><dt>Returned model / provider</dt><dd>${esc(r.returned_model || "Not reported")} / ${esc(r.returned_provider || "Not reported")}</dd><dt>Provider request ID</dt><dd>${esc(r.provider_request_id || "Not reported")}</dd><dt>Observed prompt tokens</dt><dd data-usage="prompt_tokens">${num(r.prompt_tokens)}</dd><dt>Observed completion tokens</dt><dd data-usage="completion_tokens">${num(r.completion_tokens)}</dd><dt>Observed total tokens</dt><dd data-usage="total_tokens">${num(r.total_tokens)}</dd><dt>Reported reasoning tokens</dt><dd data-usage="reasoning_tokens">${num(r.reasoning_tokens)}</dd><dt>Reported cached / cache-write tokens</dt><dd><span data-usage="cached_tokens">${num(r.cached_tokens)}</span> / <span data-usage="cache_write_tokens">${num(r.cache_write_tokens)}</span></dd><dt>Usage interpretation</dt><dd>${esc(human(r.usage_status || "unavailable"))}. Reasoning and cache counts can be subsets; do not add them to the reported total. Provider accounting conventions may differ.</dd><dt>Repetitions / execution</dt><dd>${num(data.protocol?.repetitions)} / ${esc(human(data.protocol?.execution || "Not recorded"))}</dd><dt>Source packet SHA-256</dt><dd>${esc(r.source_packet_sha256 || "Not recorded")}</dd><dt>Request state</dt><dd>${esc(human(r.state))}</dd><dt>Response contract</dt><dd>${r.structural_valid?'Accepted; semantic correctness remains unverified':'Not accepted; no semantic success is inferred'}</dd><dt>Scoring exclusions</dt><dd>${r.unscored_probe_ids?.length?r.unscored_probe_ids.map(esc).join(', '):r.track==='legacy'?'All legacy judgments are advisory without an adjudicated key':'None recorded'}</dd></dl>${r.issues?.length?'<h3>Recorded issues</h3><ul>'+r.issues.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':''}<div class="link-row">${link(r.request_path,'Exact request')}${link(r.record_path,'Request receipt')}${link(r.raw_path,'Raw output')}${link(r.blueprint_path,'Draft blueprint JSON')}</div>${r.blueprint_path?'<p class="notice warn">Exported blueprint is an unapproved model draft. Contract checks and draft-event matches do not establish an executable or business-approved process.</p>':''}${judgments?'<div class="table-wrap"><table class="mini-table"><thead><tr><th>Item</th><th>Observed judgment</th><th>Provisional comparison</th><th>Source units</th><th>Model rationale, unverified</th></tr></thead><tbody>'+judgments+'</tbody></table></div>':'<p>No assessed judgments are available for this request.</p>'}${packet?'<details><summary>Inspect exact source and task packet</summary><pre>'+esc(JSON.stringify(packet,null,2))+'</pre></details>':'<p class="small">Exact task packet is not available in this snapshot.</p>'}`;
    $('close-detail').addEventListener('click',()=>{const id=selected;selected=null;detail();table();document.querySelector(`[data-inspect="${CSS.escape(id)}"]`)?.focus();});
  }
  function semanticNote(probe) {
    const note=observationFor(probe.id);
    if(!note) return '';
    return `<aside class="semantic-note" data-probe="${esc(probe.id)}"><p class="eyebrow">Postrun advisory observation</p><h4>${esc(probe.id)}: description and obligation</h4><p>The frozen draft says <strong>${esc(human(note.frozen_draft_label))}</strong>. A response says <strong>${esc(human(note.observed_label))}</strong>. Both a specification reading and a descriptive reading are defensible. Draft disagreement alone does not establish a model error.</p><p><strong>Current treatment:</strong> the frozen label, disagreement and denominator are retained. No retroactive scoring exclusion. Human adjudication is pending.</p><details><summary>Inspect the two interpretations</summary>${note.interpretations.map(item=>`<p><strong>${esc(human(item.label))}:</strong> ${esc(item.reading)}</p><p>Assumption: ${esc(item.additional_assumption)}</p>`).join('')}<p>This automated observation followed a model response; it is not a blind review.</p>${link('review/postrun-semantic-observations.md','Read the retained advisory note on GitHub')}</details></aside>`;
  }
  function sources() {
    $('source-cases').innerHTML=data.case_bank.cases.map(c=>`<article class="source-case"><p class="eyebrow">${esc(c.id)}</p><h3>${esc(c.title)}</h3><p>${c.documents.length} fictional documents · ${c.probes.length} draft propositions</p>${c.probes.map(semanticNote).join('')}<details><summary>Read source documents</summary>${c.documents.map(d=>`<h4>${esc(d.id)}</h4>${d.units.map(u=>`<div class="source-unit"><b>${esc(u.id)}</b><p>${esc(u.text)}</p></div>`).join('')}`).join('')}</details><details><summary>Inspect provisional propositions</summary>${c.probes.map(p=>`<div class="probe"><strong>${esc(p.id)}</strong><p>${esc(p.statement)}</p><span>${esc(human(p.dimension))} · draft disposition: ${esc(human(p.draft_disposition))} · human adjudication pending${p.id==='policy-transition-P05'?' · excluded before inference, assigned count retained':''}</span></div>`).join('')}</details></article>`).join('');
  }
  function counterfactualAdvisory() {
    const review=data.counterfactual_advisory;
    if(!review) {$('metamorphic-advisory').innerHTML='';return;}
    const summary=review.summary;
    $('metamorphic-advisory').innerHTML=`<aside class="semantic-note"><p class="eyebrow">Postrun advisory · threshold counterfactual only</p><h3>Interpret the observed deviations</h3><p>${num(summary.proposed_relations_satisfied)} of ${num(summary.assigned_pairs)} proposed relation pairs were satisfied; ${num(summary.proposed_relations_violated)} deviations remain counted. ${num(summary.scope_sensitive_P01_deviations)} concern the scope of the P01 approval rule; ${num(summary.observed_P07_invariance_deviations)} is a P07 label-invariance deviation. They are not adjudicated model errors.</p><p><strong>Design limitation:</strong> the threshold changed from EUR 12,000 to EUR 15,000, but the request also changed from eight propositions to six. This is not a strict single-variable full-prompt experiment, so the threshold edit alone cannot be assigned as the cause.</p><p>The frozen expected labels, counts and exclusions are unchanged. Human adjudication remains pending; no majority vote supplies gold.</p><details><summary>Read the scope and interpretation notes</summary>${review.observations.map(note=>`<h4>${esc(note.probe_id)}</h4><p>${esc(note.analysis)}</p><p>${esc(note.recommendation)}</p>`).join('')}<p>${esc(review.review_blinding)}</p></details><p>${link('review/counterfactual-advisory-review.md','Read the retained counterfactual advisory on GitHub')}</p></aside>`;
  }
  function metamorphic() {
    const rows=analysis()?.metamorphic || [];
    if (!rows.length) {$('metamorphic-results').innerHTML='<p class="empty">No executed metamorphic comparison is available. The seven proposed checks are design hypotheses, not observed outcomes.</p>';return;}
    $('metamorphic-results').innerHTML='<div class="table-wrap"><table class="mini-table"><caption>BASELINE AND VARIANT PREDICTIONS; NO SEMANTIC GOLD INFERRED</caption><thead><tr><th>Check</th><th>Configuration</th><th>Observed / assigned pairs</th><th>Observed relations</th><th>Inspect</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${esc(r.check_id)}</td><td>${esc(r.model)}</td><td>${num(r.observed_pairs)} / ${num(r.assigned_pairs)}<small>${num(r.missing_pairs)} missing · ${num(r.unscored_pairs||0)} unscored</small></td><td>${r.checks.filter(c=>c.satisfied===true).length} satisfied; ${r.checks.filter(c=>c.satisfied===false).length} violated<small>Among assessed relation pairs</small></td><td><details><summary>Pair observations</summary><ul>${r.checks.map(c=>`<li>${esc(c.id)}: ${esc(human(c.relation))}; baseline ${esc(human(c.baseline))}; variant ${esc(human(c.variant))}; ${c.satisfied===true?'observed relation satisfied':c.satisfied===false?'observed relation violated':'not scored or unavailable'}</li>`).join('')}</ul></details></td></tr>`).join('')+'</tbody></table></div>';
  }
  function legacy() {
    const rows=attempts().filter(r=>r.track==='legacy');
    if (!rows.length) {$('legacy-results').innerHTML='<p class="empty">No automated first-pass observations have been recorded. The human review packet is ready; no annotation is claimed.</p>';return;}
    $('legacy-results').innerHTML=(rows.some(r=>r.judgments?.length)?'<p class="small">Retained responses use blind item IDs. The display-only crosswalk identifies ITEM-A as P002, ITEM-B as P013 and ITEM-C as P036 after inference. Original labels are not included in this crosswalk or the model requests.</p>':'')+'<div class="table-wrap"><table class="mini-table"><caption>AUTOMATED ADVISORY JUDGMENTS; HUMAN ADJUDICATION PENDING</caption><thead><tr><th>Configuration</th><th>Request state</th><th>Retained judgments</th><th>Evidence</th></tr></thead><tbody>'+rows.map(r=>`<tr><td>${configLabel(r)}</td><td>${stateTag(r)}</td><td>${r.judgments?.length?r.judgments.map(j=>`<p><strong>${esc(legacyDisplay(j.id))}</strong>: ${esc(human(j.predicted))}<small>${esc(j.rationale||'')}</small></p>`).join(''):'No usable judgments; no replacement label inferred'}</td><td>${link(r.raw_path,'Raw advisory response')}<br>${link(r.record_path,'Receipt')}</td></tr>`).join('')+'</tbody></table></div>';
  }
  function download(kind) {
    const rows=visible(),meta={revision:data.revision,status:data.status,qualified:false,independent_human_reviews:0,case_bank_sha256:data.case_bank_sha256,source_reference:data.source_reference,filters:{...states},scope:'Internal engineering observations; provisional expectations; no ranks or independent semantic accuracy',budget:data.budget,configurations:data.configurations,legacy_identity_map:data.legacy_identity_map,postrun_semantic_observations:data.postrun_semantic_observations,counterfactual_advisory:data.counterfactual_advisory,reasoning_effort:data.protocol?.reasoning_effort,max_output_tokens:data.protocol?.max_output_tokens,repetitions:data.protocol?.repetitions,filter_case:states.case,filter_model:states.model,filter_track:states.track,filter_state:states.state};
    let body,type;
    if(kind==='json'){body=JSON.stringify({...meta,attempts:rows},null,2)+'\n';type='application/json';}
    else {const q=value=>'"'+String(value??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const columns=['revision','status','qualified','model','provider','returned_model','returned_provider','provider_request_id','prompt_tokens','completion_tokens','total_tokens','reasoning_tokens','cached_tokens','cache_write_tokens','usage_status','reasoning_effort','max_output_tokens','repetitions','case_id','track','variant','state','structural_valid','assigned','classified','missing','unassessed','scored_assigned','unscored_classified','matches_draft','divergences','cost_usd','cost_status','elapsed_seconds','blueprint_path','source_reference','case_bank_sha256','filter_case','filter_model','filter_track','filter_state'];body=columns.join(',')+'\n'+rows.map(r=>columns.map(c=>q(c==='provider'?configFor(r)?.provider:c in r?r[c]:meta[c])).join(',')).join('\n')+'\n';type='text/csv';}
    const url=URL.createObjectURL(new Blob([body],{type:type+';charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='blueprintbench-next-cycle-selection.'+kind;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
  }
  function renderSelection(){table();detail();const url=new URL(location.href);for(const [k,v]of Object.entries(states)){if(v==='all')url.searchParams.delete(k);else url.searchParams.set(k,v);}history.replaceState(null,'',url);}
  async function load(){
    try{
      const response=await fetch('downloads/blueprintbench/next-cycle-results.json',{cache:'no-store'});if(!response.ok)throw new Error('Results unavailable');data=await response.json();
      if(data.qualified!==false || data.independent_human_reviews!==0 || !Array.isArray(data.case_bank?.cases))throw new Error('Unsupported evidence boundary');
      data.task_packets ||= [];
      options($('case-filter'),[...data.case_bank.cases.map(c=>[c.id,c.title]),['legacy-contested','Legacy disputed propositions']]);
      options($('model-filter'),[...new Set(attempts().map(r=>r.model))].sort().map(m=>[m,m]));
      const params=new URL(location.href).searchParams;for(const key of Object.keys(states)){const control=$(key+'-filter');if([...control.options].some(o=>o.value===params.get(key)))states[key]=params.get(key);control.value=states[key];control.addEventListener('change',()=>{states[key]=control.value;selected=null;renderSelection();});}
      $('reset').addEventListener('click',()=>{for(const key of Object.keys(states)){states[key]='all';$(key+'-filter').value='all';}selected=null;renderSelection();});
      $('export-json').disabled=!analysis();$('export-csv').disabled=!analysis();$('export-json').addEventListener('click',()=>download('json'));$('export-csv').addEventListener('click',()=>download('csv'));
      $('review-timing').innerHTML = '<p><strong>Before inference: policy-transition-P05.</strong> Retained in assigned and classified counts, excluded from provisional matching because the rubric was already sensitive.</p>' + (data.postrun_semantic_observations?'<p><strong>After observing a response: bank-change-P07.</strong> Two defensible readings were documented. Its original supported label, denominator and disagreement count remain unchanged. No retroactive exclusion was added. '+link('review/postrun-semantic-observations.md','Read the postrun advisory note')+'</p>':'');
      $('integrity').innerHTML = '<p class="small"><strong>Published case-bank SHA-256</strong><br><code>'+esc(data.case_bank_sha256)+'</code></p>' + Object.entries(analysis()?.inputs || {}).map(([key,value])=>'<p class="small"><strong>'+esc(human(key))+'</strong><br><code>'+esc(value)+'</code></p>').join('');
      $('limits').innerHTML=data.limitations.map(x=>'<li>'+esc(x)+'</li>').join('');
      $('raw-evidence-link').href=`https://github.com/sev7enITA/PALO-BlueprintBench/tree/${encodeURIComponent(data.source_reference)}/${data.campaign_path}`;
      summary();budget();chart();table();sources();counterfactualAdvisory();metamorphic();legacy();
    }catch(error){$('load-state').classList.add('warn');$('load-state').textContent='Test records could not be loaded. No counts or costs are inferred. Use the source repository links below.';}
  }
  load();
})();
